  if(M.rainPlan===undefined){
    const wx=((M.meta&&M.meta.weather)||'').toLowerCase();
    if(wx==='drizzle'){
      if(M.rand()<0.40){
        const overAt=12+Math.floor(M.rand()*24);       // strikes overs 12-35 of the chase
        const lost=6+Math.floor(M.rand()*13);          // 6-18 overs lost
        M.rainPlan={over:overAt,lost:lost};
      }else M.rainPlan=null;
    }else M.rainPlan=null;
  }
  if(!M.rainPlan||M.rainDone||M.inns!==1)return;
  if(inn.legal%6!==0||Math.floor(inn.legal/6)!==M.rainPlan.over)return;
  // apply the interruption: overs lost, DLS-revised target
  const w=inn.wkts,legal=inn.legal;
  let lost=M.rainPlan.lost;
  const maxLost=Math.floor((300-legal-30)/6);          // always leave >=5 overs
  if(maxLost<1){M.rainDone=true;return}
  if(lost>maxLost)lost=maxLost;
  const uNow=(300-legal)/6,uAfter=uNow-lost;
  const Rfull=foDLSRes(50,0);
  const Rlost=foDLSRes(uNow,w)-foDLSRes(uAfter,w);
  const R2=Math.max(0.05,(Rfull-0)-Rlost);             // chase began with full resources
  const S1=M.innings[0]?M.innings[0].runs:0;
  const newTarget=Math.max(inn.runs+1,Math.floor(S1*(R2/Rfull))+1);
  M.rainCap=300-lost*6;
  M.rainDone=true;
  const oldT=M.target;M.target=newTarget;
