function banner(){
  const a=M.innings[0],b=M.innings[1];let res,marg;
  if(b.runs>=M.target){res=b.batTeam;marg=`by ${10-b.wkts} wickets (${foBallCap()-b.legal} balls left)`}
  else if(b.runs===M.target-1){res=null;marg='Match tied'}
  else{res=a.batTeam;marg=`by ${M.target-1-b.runs} runs`}
  // MoM: top runs+2*wkts... simple
  let best=null,bv=-1;
  for(const inn of M.innings){for(const s of inn.bat){const v=s.r;if(v>bv){bv=v;best=s.p.name+' '+s.r}}
    for(const k in inn.bowlers){const r=inn.bowlers[k];const v=r.w*35;if(v>bv){bv=v;best=k+' '+r.w+'w'}}}
  M.result={winner:res,text:(res?res+' win '+marg:'Match tied'),mom:best};
  if(typeof onMatchEnd==='function')onMatchEnd();
}
// ---------- drivers ----------
function needUserBowlerPick(){
  const inn=M.innings[M.inns];
  return inn&&!M.done&&inn.batTeam!==M.user.name&&inn.legal%6===0;
}
function doBall(){if(!M||M.done)return;stepBall()}
function playOver(){if(!M||M.done)return;const inn=M.innings[M.inns];const start=inn.legal;const i0=M.inns;
  do{stepBall()}while(!M.done&&M.inns===i0&&M.innings[M.inns].legal<start+6&&M.innings[M.inns].legal>start-1)}
function simN(n){for(let i=0;i<n&&!M.done;i++){playOverAuto()}}
function playOverAuto(){if(M.done)return;const i0=M.inns;const inn=M.innings[M.inns];const start=inn.legal;
  while(!M.done&&M.inns===i0&&M.innings[M.inns].legal<start+6){autoPick();stepBall()}}
function autoPick(){
  const inn=M.innings[M.inns];
  if(inn.batTeam!==M.user.name&&inn.legal%6===0){
    const ov=Math.floor(inn.legal/6);
    const pl=plannedBowler(inn,ov);
    UI.userBowler=(pl||aiPickBowler(inn,ov)).name;
  }
}
function simInnings(){const i0=M.inns;while(!M.done&&M.inns===i0){autoPick();stepBall()}}
function simAll(){let g=0;while(!M.done&&g++<3000){autoPick();stepBall()}}

