  function fo55Flag(nat){return `<span class="fo-flag" title="${esc(nat||'')}">${FO55_FLAGS[nat]||'🏳️'}</span>`}
  function fo55WageBill(t){return (t&&t.players?t.players.reduce((s,p)=>s+(+p.wage||0),0):0)}
  function fo55RoundDate(roundNo){const d=new Date(2026,6,4);d.setDate(d.getDate()+7*roundNo);return d.toLocaleDateString('en-GB',{weekday:'short',day:'numeric',month:'short',year:'numeric'})}
  function fo55NextFixture(){try{seasonInit();const S=App.season;if(!S)return null;for(let r=S.round;r<S.schedule.length;r++){for(const f of S.schedule[r]){if(f[0]!==App.teamIx&&f[1]!==App.teamIx)continue;if(S.played[fixtureKey(r,f)]!==undefined)continue;const home=GD.teams[f[0]],away=GD.teams[f[1]],opp=GD.teams[f[0]===App.teamIx?f[1]:f[0]];return{round:r,f,home,away,opp,ground:home.ground,pitch:home.name===userTeam().name?(home.homePitch||groundPitch(home.ground)):groundPitch(home.ground),weather:WXLIST[(r*7+f[0]*3)%WXLIST.length],isHome:f[0]===App.teamIx,date:fo55RoundDate(r)}}}}catch(e){}return null}

  // Player links now carry country flags everywhere names are rendered as links.
  try{
    playerLink=function(p){return `<a href="#/player?n=${encodeURIComponent(p.name)}" title="${esc(playerTip(p))}">${fo55Flag(p.nat)}${esc(p.name)}</a>`};
    playerMini=function(p){return `<span class="player-hoverable" title="${esc(playerTip(p))}">${fo55Flag(p.nat)}${esc(p.name)}</span>`};
  }catch(e){}

  // No team editor in playable builds.
  pgEditor=function(){document.getElementById('page').innerHTML=crumb(userTeam().name,'Editor removed')+'<div class="panel"><div class="pad">The team editor is disabled in this build so managers cannot alter squads during a save.</div></div>'};
  function fo55Sanitize(){document.querySelectorAll('a[href="#/editor"]').forEach(a=>a.remove());if(location.hash.indexOf('#/editor')===0){location.hash='#/squad'}}
  window.addEventListener('hashchange',()=>setTimeout(fo55Sanitize,0));
  setInterval(fo55Sanitize,1500);

  // Header live controls: only one return-to-current-match icon.
  function fo55LiveLabel(){if(M&&M.meta)return `${M.meta.home} v ${M.meta.away}`;if(App.pending)return `${App.pending.home} v ${App.pending.away}`;return 'current match'}
  // retired: the orange-dot + teal return-arrow cluster is redundant with the
