  setInterval(fo55LiveTopbar,450);window.addEventListener('hashchange',()=>setTimeout(fo55LiveTopbar,0));

  // Minimal club home.
  pgClub=function(){seasonInit();econInit();const t=userTeam(),S=App.season,nf=fo55NextFixture(),rowsL=leagueRows(),pos=rowsL.findIndex(x=>x.nm===t.name)+1;const xi=pickXI(t);const last=App.results.slice(-3).reverse();const table=rowsL.map((x,i)=>`<tr ${x.nm===t.name?'style="background:#eef8fb"':''}><td>${i===0?'🏆':i+1}</td><td>${esc(x.nm)}</td><td class="n">${x.p}</td><td class="n">${x.w}</td><td class="n">${x.l}</td><td class="n">${x.nrr>=0?'+':''}${x.nrr.toFixed(2)}</td><td class="n"><b>${x.pts}</b></td></tr>`).join('');const recent=last.map(r=>`<tr class="rowlink" onclick="location.hash='#/scorecard?i=${r.ix}'"><td>${esc(r.date)}</td><td>${esc(r.home)} v ${esc(r.away)}</td><td>${esc(r.result.text)}</td></tr>`).join('')||'<tr><td colspan="3" class="small">No matches played yet.</td></tr>';const topPlayers=xi.slice(0,5).map((p,i)=>`<tr><td>${i+1}</td><td>${playerLink(p)}${p.keeper?' †':''}</td><td>${prole(p.role)}</td><td class="n">${p.rating}</td></tr>`).join('');document.getElementById('page').innerHTML=`<div class="fo-club-min">${crumb(t.name,'Club')}<div class="welcome-hero"><div><div class="eyebrow">Club home</div><h1>${esc(t.name)}</h1><p>A clean match-day dashboard: next fixture, league position, bank, and the few decisions that matter now.</p><div class="action-row" style="margin-top:12px"><button class="primary" onclick="location.hash='#/orders'">Set orders</button><button onclick="location.hash='#/matches'">Matches</button><button onclick="location.hash='#/squad'">Squad</button></div></div><div class="kpi-grid hero-kpis"><div class="kpi-card"><span>Round</span><b>${Math.min(S.round+1,S.schedule.length)}</b></div><div class="kpi-card"><span>League position</span><b>${pos>0?pos:'-'}</b></div><div class="kpi-card"><span>Bank</span><b>${fo55Money(App.fin&&App.fin.bank)}</b></div><div class="kpi-card"><span>Wage bill</span><b>${fo55Money(fo55WageBill(t))}</b></div></div></div><div class="page-grid-2"><div><div class="panel"><h4>Next match</h4><div class="pad">${nf?`<table class="kv"><tr><td>Opponent</td><td><b>${esc(nf.opp.name)}</b></td></tr><tr><td>Date</td><td>${esc(nf.date)}</td></tr><tr><td>Venue</td><td>${nf.isHome?'Home':'Away'} · ${esc(nf.ground)}</td></tr><tr><td>Conditions</td><td><span title="${pitchTip(nf.pitch)}">${esc(nf.pitch)}</span> pitch · <span title="${wxTip(nf.weather)}">${esc(nf.weather)}</span></td></tr></table><div class="action-row"><button class="primary" onclick="location.hash='#/orders'">Prepare orders</button><button onclick="location.hash='#/matches'">Round page</button></div>`:'<div class="empty-state">Season complete. Open Matches to start the next season.</div>'}</div></div><div class="panel"><h4>Recent results</h4><div class="pad"><table><tr><th>Date</th><th>Match</th><th>Result</th></tr>${recent}</table></div></div></div><div><div class="panel"><h4>🏆 League standings</h4><div class="pad"><table><tr><th></th><th>Club</th><th class="n">P</th><th class="n">W</th><th class="n">L</th><th class="n">NRR</th><th class="n">Pts</th></tr>${table}</table></div></div><div class="panel"><h4>Likely XI</h4><div class="pad"><table><tr><th>#</th><th>Player</th><th>Role</th><th class="n">Rat</th></tr>${topPlayers}</table><div class="small" style="margin-top:5px"><a href="#/squad">Open full squad</a></div></div></div></div></div></div>`;fo55Sanitize();fo55LiveTopbar()};

  // Orders: show starter blank spells and keep the setup narrower.
  const fo55OldPgOrders=pgOrders;
  function fo55SeedSpells(){if(!App.orders.spells)App.orders.spells={north:[],south:[]};for(const end of ['north','south'])App.orders.spells[end]=App.orders.spells[end]||[];if(!App.orders.spells.north.length&&!App.orders.spells.south.length){App.orders.spells.north=[{bowler:'',first:1,n:5,field:'att',tactic:0},{bowler:'',first:11,n:5,field:'bal',tactic:0},{bowler:'',first:41,n:5,field:'def',tactic:0}];App.orders.spells.south=[{bowler:'',first:2,n:5,field:'att',tactic:0},{bowler:'',first:12,n:5,field:'bal',tactic:0},{bowler:'',first:42,n:5,field:'def',tactic:0}]}}
  pgOrders=function(){fo55SeedSpells();fo55OldPgOrders();document.querySelectorAll('.bowlingEndName button').forEach(b=>{if(/add spell/i.test(b.textContent))b.title='Add another spell to this end'});fo55Sanitize()};

  // Toss animation restored: starting a pending match always shows the coin before play begins.
  startPendingIfNeeded=function(){if(M&&!M.done)return;if(!App.pending)return;if(window.__ap){clearInterval(window.__ap);window.__ap=null}
    // the fixture stores an index AND a name; the index can go stale when a
    // league snapshot or the Circuit rebuilds GD.teams, so the name is the truth
    const t=userTeam();let o=GD.teams[App.pending.oppIx];
    if(App.pending.away&&(!o||o.name!==App.pending.away)){const nIx=GD.teams.findIndex(x=>x&&x.name===App.pending.away);if(nIx>=0){App.pending.oppIx=nIx;o=GD.teams[nIx]}}
    if(!o||o===t)return;
    if(App.pending.home&&t&&App.pending.home!==t.name)App.pending.home=t.name;
    M=newMatch(t,o,App.pending.pitch,App.pending.seed);M.meta=Object.assign({},App.pending);M.isUserMatch=true;const auto=!App.orders.tossCall;const call=App.orders.tossCall||(M.rand()<0.5?'H':'T');if(auto)App.orders.tossCall=call;App.tossState={stage:'flip',call};
    const my=M;   // the coin belongs to THIS match: never resolve a rebuilt or started one
    window.setTimeout(()=>{if(!M||M!==my||M.done||M.batFirstTeam)return;try{resolveToss(call)}catch(e){App.tossState={stage:'call'};try{renderMatch()}catch(e2){}}if(auto)window.setTimeout(()=>{if(App.orders.tossCall===call)App.orders.tossCall=''},80)},1400)};

  // Highlights: every ball is still simulated, but the broadcast only LANDS on
  // the ones worth watching - boundaries, wickets, real milestones, and the
  // last two overs of a chase. A full match becomes a three-minute cut.
  function fo55Interesting(){try{
    const L=M.log&&M.log[0];if(!L)return true;
    if(L.mile&&!/^End of over/i.test(L.txt||''))return true;
    if(L.out==='4'||L.out==='6')return true;
    if(typeof isWkt==='function'&&isWkt(L.out))return true;
    const inn=M.innings[M.inns];
    if(M.target&&inn&&(foBallCap()-inn.legal)<=12)return true;
    return false;
  }catch(e){return true}}
  function fo55HighlightStep(){
    let g=0;
    do{autoPick();stepBall();g++}while(M&&!M.done&&!fo55Interesting()&&g<60);
    renderMatch();
  }
  function fo55EnsureAutoplay(){if(window.__ap||!M||M.done||!M.innings||!M.innings[M.inns])return;window.__ap=setInterval(()=>{if(!M||M.done||(location.hash||'').split('?')[0]!=='#/match'){clearInterval(window.__ap);window.__ap=null;if(M&&M.done)renderMatch();return}doBall()},UI.apMs||1600)}
  function fo55IsTalentText(txt){return /SIX MACHINE|Finisher|PARTNERSHIP BREAKER|New Ball Specialist|Golden Arm|Mystery Ball|Bouncer|Lightning Hands|Rocket Arm|Safe Hands|Miser|Spin Killer|Pace Hunter|Fast Starter|Anchor|death specialist/i.test(txt||'')}
  function fo55CommPass(L,filter){filter=filter||'all';const txt=L.txt||'';if(filter==='all')return true;if(filter==='wickets')return isWkt(L.out)||/WICKET|out for|Partnership ends/i.test(txt);if(filter==='boundaries')return L.out==='4'||L.out==='6'||/FOUR|SIX/i.test(txt);if(filter==='overs')return L.mile||/End of over|DRINKS|Innings break|CHASE BEGINS|PLAY BEGINS/i.test(txt);if(filter==='fielding'){const o9=String(L.out||'');if(o9==='wC'||o9==='wRO'||o9==='wST')return true;return /DROPPED!|Misfield|Brilliant (diving|stop|fielding)|runs saved|RUN OUT!|direct hit|takes (a|the|it|his|the sharpest).{0,24}catch|caught (behind|at|by)|saves (one|two|the|four)|cuts it off|steal the single/i.test(txt);}if(filter==='talents')return fo55IsTalentText(txt);if(filter==='highlights')return L.mile||isWkt(L.out)||L.out==='4'||L.out==='6'||fo55IsTalentText(txt)||/DROPPED|FIFTY|HUNDRED/i.test(txt);return true}
  function fo55RenderText(txt){let h=esc(txt||'');['SIX MACHINE','PARTNERSHIP BREAKER','New Ball Specialist','Golden Arm','Mystery Ball','Bouncer','Finisher','Lightning Hands','Rocket Arm','Safe Hands','Miser','Spin Killer','Pace Hunter','Fast Starter','Anchor','death specialist'].forEach(n=>{const re=new RegExp('('+n.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+')','ig');h=h.replace(re,'<span class="talent-hit">$1</span>')});return h}
  function fo55CommentRows(log,filter,limit){return (log||[]).filter(L=>fo55CommPass(L,filter)).slice(0,limit||120).map(L=>{const cls=L.out==='4'?'four':L.out==='6'?'six':isWkt(L.out)?'W':'';const bg=isWkt(L.out)?'background:#fbe9e7;':(L.out==='6'?'background:#fdf6df;':(L.out==='4'?'background:#eef4fa;':''));const ability=fo55IsTalentText(L.txt)?' ability-row':'';return `<div class="bl ${L.mile?'mile':''}${ability}" style="${bg}"><b class="${cls}">${esc(L.no||'')}</b> ${fo55RenderText(L.txt)}</div>`}).join('')||'<span class="small">No commentary matches this filter.</span>'}
  function fo55FilterSelect(){const cur=UI.commFilter||'all';return `<span class="comm-filter"><span>Display</span><select onchange="UI.commFilter=this.value;renderMatch()">${[['all','All commentary'],['highlights','Highlights'],['wickets','Wickets'],['boundaries','Boundaries'],['fielding','Fielding'],['overs','Over summaries'],['talents','Ability triggers']].map(([v,l])=>`<option value="${v}" ${cur===v?'selected':''}>${l}</option>`).join('')}</select></span>`}
  function fo55LiveScorecardForInnings(inn){if(!inn)return '<div class="small">No innings yet.</div>';const bat=inn.bat.filter(b=>b.b>0||b.out||(!b.out&&(b===inn.bat[inn.striker]||b===inn.bat[inn.nonstriker]))).map(b=>`<tr><td>${playerLink(b.p)}${!b.out?' *':''}</td><td class="small">${esc(b.out||'not out')}</td><td class="n"><b>${b.r}</b></td><td class="n">${b.b}</td><td class="n">${b.f4}</td><td class="n">${b.f6}</td><td class="n">${b.b?(100*b.r/b.b).toFixed(1):'-'}</td></tr>`).join('');const bowl=Object.values(inn.bowlers||{}).map(r=>`<tr><td>${playerLink(r.p)}</td><td class="n">${Math.floor(r.b/6)}.${r.b%6}</td><td class="n">${r.r}</td><td class="n"><b>${r.w}</b></td><td class="n">${r.b?(r.r/(r.b/6)).toFixed(2):'-'}</td></tr>`).join('')||'<tr><td colspan="5" class="small">Bowling card appears after the first ball.</td></tr>';const ex=inn.extras||{wd:0,nb:0,b:0,lb:0};const rr=inn.legal?(inn.runs/(inn.legal/6)).toFixed(2):'0.00';return `<div class="live-score-mini ftp-no-bars"><table class="ftp-scorecard"><thead><tr><th colspan="2">${esc(inn.batTeam)}</th><th class="n">R</th><th class="n">B</th><th class="n">4s</th><th class="n">6s</th><th class="n">SR</th></tr></thead><tbody>${bat}</tbody><tfoot><tr><th>Extras</th><td>(b ${ex.b}, lb ${ex.lb}, w ${ex.wd}, nb ${ex.nb})</td><td class="n"><b>${ex.wd+ex.nb+ex.b+ex.lb}</b></td><td colspan="4"></td></tr><tr><th>Total</th><td>(${inn.wkts} wickets, ${Math.floor(inn.legal/6)}.${inn.legal%6} overs)</td><td class="n"><b>${inn.runs}</b></td><td colspan="4">RR: ${rr}</td></tr></tfoot></table><table class="ftp-bowling"><thead><tr><th>Bowling</th><th class="n">O</th><th class="n">R</th><th class="n">W</th><th class="n">Econ</th></tr></thead><tbody>${bowl}</tbody></table></div>`}
  function fo55Worm(){if(!M||!M.worm)return '<div class="small">No worm data yet.</div>';const all=M.worm.filter(w=>w&&w.length);if(!all.length)return '<div class="small">No worm data yet.</div>';const mx=Math.max(10,...all.flatMap(w=>w.map(p=>p[1])))+10,mo=Math.max(50,...all.flatMap(w=>w.map(p=>p[0])));const line=(w,col)=>`<polyline fill="none" stroke="${col}" stroke-width="2" points="${w.map(p=>((12+p[0]/mo*520).toFixed(1))+','+((180-p[1]/mx*165).toFixed(1))).join(' ')}"/>`+w.filter((p,i)=>i>0&&(p[2]||0)>(w[i-1][2]||0)).map(p=>`<circle cx="${(12+p[0]/mo*520).toFixed(1)}" cy="${(180-p[1]/mx*165).toFixed(1)}" r="3" fill="#a33328"/>`).join('');return `<svg viewBox="0 0 545 190" style="width:100%;max-width:620px;height:210px;border-bottom:1px solid #bbb">${M.worm[0]?line(M.worm[0],'#2d6a8f'):''}${M.worm[1]?line(M.worm[1],'#c8a13a'):''}</svg><div class="small"><span style="color:#2d6a8f">■</span> ${esc(M.innings[0]?M.innings[0].batTeam:'1st innings')} &nbsp; <span style="color:#c8a13a">■</span> ${esc(M.innings[1]?M.innings[1].batTeam:'2nd innings')} &nbsp; ● wicket</div>`}
  function fo55OrdersPanel(){const O=App.orders||{};const bat=(O.batOrder||[]).slice(0,11).map((n,i)=>`<tr><td class="n">${i+1}</td><td>${esc(n)}</td></tr>`).join('');const overs=(O.compiled||[]).map((n,i)=>n?`<span class="phasechip" title="over ${i+1}: ${esc(n)}">${i+1}</span>`:'').join(' ');return `<table><tr><th colspan="2">Batting order</th></tr>${bat||'<tr><td colspan="2" class="small">No batting order saved.</td></tr>'}</table><div style="margin-top:8px"><b class="small">Bowling map</b><br>${overs||'<span class="small">No bowling map saved.</span>'}</div><div class="small" style="margin-top:6px"><a href="#/orders">Open full orders page</a></div>`}
  function fo55Rivalry(){if(!M||!M.meta)return '<div class="small">No rivalry yet.</div>';const A=M.meta.home,B=M.meta.away;
    // Circuit opponents: the passport is the truth (App.results is replaced by
    // league snapshots, which was zeroing this tab against clubs played often)
    try{if(window.foCxH2H){const cx=window.foCxH2H(A,B);if(cx){
      const rws=cx.rows.slice(-8).reverse().map(r=>`<tr><td>${r.at?new Date(r.at).toLocaleDateString():'-'}</td><td>${esc(r.win?cx.me+' won':cx.opp+' won')}${r.my!=null&&r.op!=null?` <span class="small">(${r.my} · ${r.op})</span>`:''}</td><td>${r.card?`<a href="${r.card}">scorecard</a>`:''}</td></tr>`).join('');
      return `<div class="status-strip"><span>${esc(cx.me)}: <b>${cx.w}</b></span><span>${esc(cx.opp)}: <b>${cx.l}</b></span><span>Ties: <b>${cx.t}</b></span></div><table style="margin-top:8px"><tr><th>Date</th><th>Result</th><th></th></tr>${rws||'<tr><td colspan="3" class="small">First meeting in this save.</td></tr>'}</table>`;
    }}}catch(e){}
    let a=0,b=0,t=0;const rows=[];for(const r of (App.results||[])){if(!((r.home===A&&r.away===B)||(r.home===B&&r.away===A)))continue;if(!r.result||!r.result.winner)t++;else if(r.result.winner===A)a++;else if(r.result.winner===B)b++;rows.push(`<tr><td>${esc(r.date)}</td><td>${esc(r.result.text)}</td><td><a href="#/scorecard?i=${r.ix}">scorecard</a></td></tr>`)}return `<div class="status-strip"><span>${esc(A)}: <b>${a}</b></span><span>${esc(B)}: <b>${b}</b></span><span>Ties: <b>${t}</b></span></div><table style="margin-top:8px"><tr><th>Date</th><th>Result</th><th></th></tr>${rows.slice(-8).reverse().join('')||'<tr><td colspan="3" class="small">First meeting in this save.</td></tr>'}</table>`}
  function fo55Partnerships(){return M.innings.filter(Boolean).map(inn=>`<div class="small"><b>${esc(inn.batTeam)}</b></div>${pshipBars(inn)||'<span class="small">No partnerships yet.</span>'}`).join('<div style="height:8px"></div>')}
  function fo55Tabs(){const tabs=['Details','Orders','Scorecard','Charts','Match Ratings','Commentary','Worm','Partnerships','Rivalry'];UI.matchTab=UI.matchTab||'Commentary';return `<div class="ftp-match-links"><h4>Links</h4>${tabs.map(t=>`<a class="${UI.matchTab===t?'on':''}" onclick="UI.matchTab='${t}';renderMatch()">${t}</a>`).join('')}</div>`}
  function fo55TabBody(){const tab=UI.matchTab||'Commentary';if(tab==='Details')return `<table class="kv"><tr><td>Ground</td><td>${esc(M.meta.ground)}</td></tr><tr><td>Pitch</td><td>${esc(M.pitch)}</td></tr><tr><td>Weather</td><td>${esc(M.meta.weather||'')}</td></tr><tr><td>Toss</td><td>${esc(App.tossState&&App.tossState.txt||'-')}</td></tr>${M.innings.filter(Boolean).map(x=>`<tr><td>${esc(x.batTeam)}</td><td>${x.runs}/${x.wkts} (${Math.floor(x.legal/6)}.${x.legal%6})</td></tr>`).join('')}</table>`;if(tab==='Orders')return fo55OrdersPanel();if(tab==='Scorecard')return M.innings.filter(Boolean).map(fo55LiveScorecardForInnings).join('<div style="height:8px"></div>');if(tab==='Match Ratings')return ratingsTable({home:M.meta.home,away:M.meta.away,innings:M.innings,result:M.result||{}});if(tab==='Worm')return fo55Worm();if(tab==='Charts')return (typeof window.foMatchCharts==='function')?window.foMatchCharts(M.innings.filter(Boolean),M.worm):fo55Worm();if(tab==='Partnerships')return fo55Partnerships();if(tab==='Rivalry')return fo55Rivalry();return ''}
  // Team talk: the one live lever. Writes the CURRENT phase's batting intent
  // (when batting) or field setting (when bowling) into App.orders - which
  // stepBall consults on every delivery - so it takes effect next ball.
  function fo55TeamTalk(){
    try{
      if(!M||M.done||!M.isUserMatch)return '';
      const inn=M.innings[M.inns];if(!inn)return '';
      const ov=Math.floor(inn.legal/6);const ph=ov<10?'pp':(ov>=40?'death':'mid');
      const phN={pp:'powerplay',mid:'middle overs',death:'death overs'}[ph];
      if(inn.batTeam===M.user.name){
        const cur=(App.orders.phaseIntent&&App.orders.phaseIntent[ph]!==undefined)?App.orders.phaseIntent[ph]:0;
        return `<div class="fo-teamtalk"><span class="tt-l">Team talk · batting, ${phN}</span>${[[-1,'Defend'],[0,'Steady'],[1,'Attack'],[2,'Launch']].map(([v,l])=>`<button class="tt-b ${cur===v?'on':''}" onclick="foTeamTalk('bat','${ph}',${v})">${l}</button>`).join('')}</div>`;
      }
      const cur=(App.orders.fieldPlan&&App.orders.fieldPlan[ph])||'bal';
      return `<div class="fo-teamtalk"><span class="tt-l">Team talk · field, ${phN}</span>${[['att','Attack'],['bal','Balanced'],['def','Defend']].map(([v,l])=>`<button class="tt-b ${cur===v?'on':''}" onclick="foTeamTalk('field','${ph}','${v}')">${l}</button>`).join('')}</div>`;
    }catch(e){return ''}
  }
  window.foTeamTalk=function(kind,ph,v){
    try{
      if(typeof ensureTactics==='function')ensureTactics();
      if(!App.orders.phaseIntent)App.orders.phaseIntent={pp:0,mid:0,death:1};
      if(!App.orders.fieldPlan)App.orders.fieldPlan={pp:'bal',mid:'bal',death:'bal'};
      if(kind==='bat')App.orders.phaseIntent[ph]=+v;else App.orders.fieldPlan[ph]=v;
      renderMatch();
    }catch(e){}
  };
  function fo55PanelForTab(){const tab=UI.matchTab||'Commentary';if(tab==='Commentary'){const controls=M.done?`<div class="oktxt" style="font-size:14px;padding:6px;background:#eaf4ea;border:1px solid #9c9"><b>${esc(M.result?M.result.text:'Match complete')}</b> · MoM: ${esc(M.result&&M.result.mom?M.result.mom:'-')}<br><span class="small"><a href="#/matches">back to round</a></span></div>`:`<div class="ctlrow"><span class="oktxt"><b>Auto-playing</b></span><span>Commentary speed</span><select title="commentary speed" onchange="UI.apHl=false;UI.apMs=+this.value;if(window.__ap){clearInterval(window.__ap);window.__ap=null}renderMatch()">${[[800,'fast'],[1600,'normal'],[3200,'slow'],[5200,'very slow']].map(([v,l])=>`<option value="${v}" ${(UI.apMs||1600)===v?'selected':''}>${l}</option>`).join('')}</select>${fo55FilterSelect()}</div><div class="small" style="color:#777;margin-bottom:6px">The match plays automatically from your saved orders.</div>`;return `<div class="panel"><h4>Commentary</h4><div class="pad"><div class="mc-controls">${controls}</div>${fo55TeamTalk()}<div class="commfeed commbig">${fo55CommentRows(M.log,UI.commFilter||'all',32)}</div></div></div>`}return `<div class="match-subpanel ${tab==='Scorecard'?'scorecard':''}"><div class="panel"><h4><span class="fo-match-tab-title"><span>${esc(tab)}</span><span class="fo-tab-actions"><a onclick="UI.matchTab='Commentary';renderMatch()">back to commentary</a><a onclick="UI.matchTab='Scorecard';renderMatch()">scorecard</a><a onclick="UI.matchTab='Match Ratings';renderMatch()">ratings</a></span></span></h4><div class="pad">${fo55TabBody()}</div></div></div>`}

  const fo55PreviousRenderMatch=renderMatch;
  // NOTE: every query is scoped to the CURRENT render root (#page - which is
  // the smooth-render staging div during a staged render). The old
  // document-wide removals gutted the LIVE page mid-staging, so the morph
  // re-created the whole tab shell on every ball - the per-ball hard refresh.
  renderMatch=function(){if(!UI.matchTab)UI.matchTab='Commentary';fo55PreviousRenderMatch();fo55LiveTopbar();const root=document.getElementById('page');if(!M||!M.innings||!M.innings[M.inns]||!root||!root.querySelector('.mc-top'))return;root.querySelectorAll('.ftp-match-shell .mc-main').forEach(mm=>root.appendChild(mm));root.querySelectorAll('.mc-cards').forEach(x=>x.remove());root.querySelectorAll('.ftp-match-shell').forEach(x=>x.remove());const top=root.querySelector('.mc-top');const shell=document.createElement('div');shell.className='ftp-match-shell';shell.innerHTML=fo55Tabs()+`<div class="ftp-match-body">${fo55PanelForTab()}</div>`;top.insertAdjacentElement('afterend',shell);if(!M.done)fo55EnsureAutoplay();fo55Sanitize()};

  // Scorecard page: keep it narrow and add match-tab navigation when a live match exists.
  const fo55OldPgScorecard=pgScorecard;
  pgScorecard=function(q){fo55OldPgScorecard(q||{});fo55LiveTopbar();const page=document.getElementById('page');if(!page)return;let nav='';if(M&&M.meta){nav=`<div class="navsub"><b>Live match tabs:</b> <a href="#/match" onclick="UI.matchTab='Commentary'">back to commentary</a> · <a href="#/match" onclick="UI.matchTab='Scorecard'">scorecard</a> · <a href="#/match" onclick="UI.matchTab='Match Ratings'">match ratings</a> · <a href="#/match" onclick="UI.matchTab='Worm'">worm</a></div>`}page.innerHTML=`<div class="fo-scorecard-wrap">${nav}${page.innerHTML}</div>`;fo55Sanitize()};

  // Round control: AI matches can be completed without touching the user's match; whole-round sim advances cleanly.
  function fo55SimMeta(f,roundNo){const home=GD.teams[f[0]],away=GD.teams[f[1]];return{home:home.name,away:away.name,ground:home.ground,pitch:home.name===userTeam().name?(home.homePitch||groundPitch(home.ground)):groundPitch(home.ground),weather:WXLIST[(roundNo*7+f[0]*3)%WXLIST.length],seed:5000+roundNo*10+f[0],date:fo55RoundDate(roundNo),comp:'league',round:roundNo,isUser:(f[0]===App.teamIx||f[1]===App.teamIx)}}
  window.completeAIRound=function(){seasonInit();const S=App.season;if(!S||S.round>=S.schedule.length){pgMatches();return}const roundNo=S.round,rd=S.schedule[roundNo]||[];let n=0;for(const f of rd){const key=fixtureKey(roundNo,f),isUser=f[0]===App.teamIx||f[1]===App.teamIx;if(isUser||S.played[key]!==undefined)continue;simBackground(f[0],f[1],fo55SimMeta(f,roundNo));n++}saveGame(false);App._digest=`<div class="panel" style="border-left:4px solid var(--blue)"><h4>AI matches completed</h4><div class="pad">${n?n+' AI fixture'+(n===1?'':'s')+' completed instantly.':'No AI fixtures left in this round.'}<div class="small">Your match was not changed.</div></div></div>`;pgMatches();fo55LiveTopbar()};
  const fo55OldCompleteRound=completeRound;
  completeRound=function(){if(window.__ap){clearInterval(window.__ap);window.__ap=null}fo55OldCompleteRound();M=null;App.pending=null;App.tossState=null;UI.matchTab='Commentary';saveGame(false);location.hash='#/matches';setTimeout(()=>{pgMatches();fo55LiveTopbar()},0)};

  pgMatches=function(){seasonInit();const t=userTeam(),S=App.season,done=S.round>=S.schedule.length,rd=done?[]:S.schedule[S.round];const fixRows=rd.map(f=>{const home=GD.teams[f[0]],away=GD.teams[f[1]],key=fixtureKey(S.round,f),isUser=f[0]===App.teamIx||f[1]===App.teamIx,playedIx=S.played[key];let act;if(playedIx!==undefined)act=`<a href="#/scorecard?i=${playedIx}">${esc(App.results[playedIx].result.text)}</a>`;else if(isUser)act=`<a href="#/orders">orders</a> · <button class="primary" onclick='startLeagueMatch([${f[0]},${f[1]}],${S.round})'>Prepare</button>`;else act='<span class="small">awaiting AI</span>';return `<tr ${isUser?'style="background:#eef4ee"':''}><td>${esc(home.name)}</td><td>${esc(away.name)}</td><td>${esc(home.ground)} <span class="small">(${groundPitch(home.ground)})</span></td><td>${act}</td></tr>`}).join('');const userF=rd.find(f=>f[0]===App.teamIx||f[1]===App.teamIx),userKey=userF?fixtureKey(S.round,userF):null,userPlayed=done||!userKey||S.played[userKey]!==undefined,aiUnplayed=rd.some(f=>!(f[0]===App.teamIx||f[1]===App.teamIx)&&S.played[fixtureKey(S.round,f)]===undefined),allPlayed=rd.every(f=>S.played[fixtureKey(S.round,f)]!==undefined);const tbl=leagueRows().map((x,i)=>`<tr ${x.nm===t.name?'style="background:#eef4ee"':''}><td>${i===0?'🏆':i+1}</td><td>${esc(x.nm)}</td><td class="n">${x.p}</td><td class="n">${x.w}</td><td class="n">${x.l}</td><td class="n">${x.t}</td><td class="n">${x.nrr>=0?'+':''}${x.nrr.toFixed(3)}</td><td class="n"><b>${x.pts}</b></td></tr>`).join('');const rows=(()=>{let out='';const rD=r=>fo55RoundDate(r).replace(/^[A-Za-z]+,\s*/,'');for(let r=0;r<S.schedule.length;r++){const lab=r<S.round?'played':(r===S.round?'current':'upcoming');out+=`<tr><td colspan="9" style="background:#eef2f5;font-weight:600;font-size:11px">Round ${r+1} · ${rD(r)} <span class="small" style="font-weight:400">(${lab})</span></td></tr>`;for(const f of S.schedule[r]){const h=GD.teams[f[0]],a=GD.teams[f[1]],isU=f[0]===App.teamIx||f[1]===App.teamIx,pIx=S.played[fixtureKey(r,f)];let res;if(pIx!==undefined){const R=App.results[pIx];res=`<td>${esc(R.result.text)}</td><td><a href="#/scorecard?i=${pIx}">sc</a></td><td><a href="#/reports?i=${pIx}">rpt</a></td><td><button onclick="replayMatch(${pIx})">replay</button></td>`;}else{res=`<td class="small">${r<S.round?'—':'not played'}</td><td></td><td></td><td></td>`;}out+=`<tr ${isU?'style="background:#eef4ee"':''}><td>${r+1}</td><td>Lg</td><td>${esc(h.name)}</td><td>${esc(a.name)}</td><td class="small">${esc(h.ground)}</td>${res}</tr>`;}}return out;})();const digest=App._digest||'';App._digest='';const buttons=done?'':`<div class="ctlrow fo-round-actions" style="margin-top:6px"><button ${aiUnplayed?'':'disabled'} onclick="completeAIRound()">Complete AI round</button>${allPlayed?`<button class="primary" onclick="completeRound()">Move to round ${S.round+2}</button>`:userPlayed?`<button class="primary" onclick="completeRound()">Complete round and advance</button>`:`<button class="warn" onclick="if(confirm('Sim your match and all remaining AI fixtures, then advance the round?'))completeRound()">Sim whole round</button>`}</div>`;document.getElementById('page').innerHTML=crumb(t.name,'Matches')+digest+`<div class="grid2"><div class="col"><div class="panel"><h4>🏆 League table - Chat Division 1</h4><div class="pad"><table><tr><th></th><th>Club</th><th class="n">P</th><th class="n">W</th><th class="n">L</th><th class="n">T</th><th class="n">NRR</th><th class="n">Pts</th></tr>${tbl}</table></div></div></div><div class="col"><div class="panel"><h4>${done?'Season '+App.seasonNo+' complete':'Round '+(S.round+1)+' of '+S.schedule.length+' - '+fo55RoundDate(S.round)}</h4><div class="pad">${done?`<div class="oktxt">Season complete.</div><button class="primary" onclick="seasonEnd()">Start season ${App.seasonNo+1}</button>`:`<table><tr><th>Home</th><th>Away</th><th>Ground</th><th></th></tr>${fixRows}</table>${buttons}<div class="small">Complete AI round only plays non-user fixtures. Sim whole round completes everything and advances to the next round.</div>`}</div></div></div></div><div class="panel"><h4>Fixtures &amp; results</h4><div class="pad"><table><tr><th>Date</th><th>Class</th><th>Home</th><th>Away</th><th>Ground</th><th>Result</th><th></th><th></th><th></th></tr>${rows}</table></div></div>`;fo55Sanitize();fo55LiveTopbar()};

  // refresh the current page with the new overrides
  try{route();fo55LiveTopbar();fo55Sanitize()}catch(e){console.error(e)}
