        ['none','Batting','Power','Rotation','Bowling','Discipline','Fielding','Keeping','Endurance','Rest']
        .map(function(k){return '<option '+(p.trainFocus===k?'selected':'')+'>'+k+'</option>';}).join('')+'</select>';
