      budgetMult: 0.963,
      focus: ["bat", "wk", "pace", "ar", "spin"],
      bias: [["batters", { vsPace: 1.10, vsSpin: 1.10, temperament: 1.14, power: 0.70 }]],
      talents: ["anchor", "busyRunner", "safeHands"],
