      (tk.bw ? pc(tk.bw, "Bowler", "<b>" + (tk.bw.w || 0) + "/" + (tk.bw.r || 0) + "</b> (" + Math.floor((tk.bw.b || 0) / 6) + "." + ((tk.bw.b || 0) % 6) + " ov)") : "") + "</div>";
