        var st2 = atCrease[n] ? "<span style='color:#15803D;font-weight:700'>batting</span>" : E(outTxt[n] && outTxt[n] !== "not out" ? outTxt[n] : "");
        var star2 = (atCrease[n] || !outTxt[n] || outTxt[n] === "not out") ? "*" : "";
