  function foCxNav() {
    try {
      var tb = document.getElementById("topbar"); if (!tb) return;
      var wrap = tb.querySelector(".fo-nav-scroll"); if (!wrap) return;
      // conquest is retired: the League is the spine, the Champions Cup beside it
      var old = wrap.querySelector("a.fo-circuit"); if (old) old.remove();
      var mkPill = function (cls, label, hash) {
        var a = wrap.querySelector("a." + cls);
        if (!a) {
          a = document.createElement("a"); a.className = cls; a.href = "#"; a.textContent = label;
          a.addEventListener("click", function (e) { e.preventDefault(); location.hash = hash; if (typeof window.route === "function") window.route(); });
        }
        a.classList.toggle("on", (location.hash || "").split("?")[0] === hash);
        return a;
      };
      var hm = mkPill("fo-home-nav", "Club", "#/home");
      var lg = mkPill("fo-lg-nav", "League", "#/league");
      // the nation record book and atlas portrait live under the League pill
      var lgH = (location.hash || "").split("?")[0];
      if (lgH === "#/nation" || lgH === "#/atlas") lg.classList.add("on");
      var pl = mkPill("fo-planet-nav", "World", "#/planet");
      // the national knockout sits beside the league it cuts across
      var fa = mkPill("fo-fa-nav", "FA Cup", "#/facup");
      var cp = mkPill("fo-cup-nav", "Cup", "#/cup");
      var jn = mkPill("fo-lore-nav", "Journal", "#/lore");
      var anchor = wrap.querySelector("a[data-nav='club'], a[data-nav='home']");
      var want = anchor ? anchor.nextSibling : wrap.firstChild;
      if (hm.parentNode !== wrap) wrap.insertBefore(hm, want);
      if (lg.parentNode !== wrap) wrap.insertBefore(lg, hm.nextSibling);
      if (pl.parentNode !== wrap) wrap.insertBefore(pl, lg.nextSibling);
      if (fa.parentNode !== wrap) wrap.insertBefore(fa, pl.nextSibling);
      if (cp.parentNode !== wrap) wrap.insertBefore(cp, fa.nextSibling);
      if (jn.parentNode !== wrap) wrap.insertBefore(jn, cp.nextSibling);
    } catch (e) {}
  }
  var foCxView = null;   // region the chapter strip is looking at (defaults to live one)
  // every tie you play on the Circuit, kept for good: score, result, your hero,
  // and a link straight to the full scorecard (the visiting clubs leave the
  // world, so this passport - not App.results - is where the record lives).
  function foCxRecordPanel(st) {
    try {
      var hist = ((st && st.hist) || []).slice().reverse();   // newest first
      if (!hist.length) return "";
      var rows = hist.slice(0, 14).map(function (h) {
        var res = h.win ? "<span class='cxr-w'>WON</span>" : "<span class='cxr-l'>LOST</span>";
        var opp = E(h.opp || "-") + (h.regionNm ? " <span class='cxr-reg'>" + E(h.regionNm) + "</span>" : "");
        var score = (h.my != null && h.op != null) ? (h.my + " &middot; " + h.op) : "";
        var hero = h.topNm && h.topR >= 0 ? "<span class='cxr-hero'>" + E(String(h.topNm).split(" ").slice(-1)[0]) + " " + h.topR + "</span>" : "";
        var link = (h.at && h.card) ? "<a href='#/friendly?id=hist-" + h.at + "'>Scorecard &rsaquo;</a>" : "<span class='cxr-no'>-</span>";
        return "<tr><td class='cxr-res'>" + res + "</td><td class='cxr-opp'>" + opp + "</td><td class='cxr-sc'>" + score + "</td><td class='cxr-h'>" + hero + "</td><td class='cxr-lk'>" + link + "</td></tr>";
      }).join("");
      return "<div class='fo-cx-record'>" +
        "<div class='fo-cx-rule'><i></i><b>YOUR CIRCUIT RECORD</b><i></i></div>" +
        "<table class='cxr-tbl'><thead><tr><th></th><th>Opponent</th><th>Score</th><th>Top score</th><th></th></tr></thead><tbody>" + rows + "</tbody></table></div>";
    } catch (e) { return ""; }
  }
