        (done ? "<span class='fo-boss-conq'>&#10003; Conquered</span>" : "") + "</div>" +
        "<div class='fo-boss-id'>" +
        "<div class='fo-boss-eb'>" + (r.final ? "The Summit &middot; The World Final" : "Region Boss &middot; " + E(r.nm)) + "</div>" +
        "<div class='fo-boss-lockup'>" +
        (crest ? "<img class='fo-boss-crest' src='" + crest + "' alt='' onerror=\"this.style.display='none'\">" : "") +
        "<div class='fo-boss-names'>" +
        "<h1>" + E(info.team || bc.nm) + "</h1>" +
        "<div class='fo-boss-lead'>" + flag + "<b>" + E(bc.leader || bc.nm) + "</b><span>" + E(bc.city) + (bc.boss && !r.final ? " Colosseum" : "") + "</span></div>" +
        "</div></div>" +
        "<div class='fo-boss-type'><span class='fo-boss-badge'>" + E(r.type || "") + "</span><span class='fo-boss-stars'>" + foBossStarHTML(pct) + "<i>" + pct + "% strength</i></span></div>" +
        (info.motif ? "<div class='fo-boss-motif'><span>CREST</span>" + E(info.motif) + "</div>" : "") +
        (brand ? "<p class='fo-boss-brand'>&ldquo;" + E(brand) + "&rdquo;</p>" : "") +
        "<div class='fo-boss-act'>" + action + "</div>" +
        "</div></header>" +
        // results strip
        "<section class='fo-boss-sec'><div class='fo-boss-sechd'><i></i><b>THE RECORD</b><i></i></div>" +
        "<div class='fo-boss-form'>" + (beads ? "<span class='fo-boss-formlabel'>FORM</span>" + beads : "<span class='fo-boss-firsttie'>No ties played &mdash; the shrine awaits its first scorecard.</span>") + "</div>" +
        (resultCards ? "<div class='fo-boss-stats'>" + resultCards + "</div>" : "") +
        "</section>" +
        // squad grid
        "<section class='fo-boss-sec'><div class='fo-boss-sechd'><i></i><b>THE XI</b><i></i></div>" +
        "<div class='fo-boss-note'>" + E(info.team || bc.nm) + " &middot; " + E(bc.leader || bc.nm) + "'s probable eleven &middot; the deck they'll bring to " + E(bc.city) + "</div>" +
        "<div class='fo-boss-squad'>" + squadHTML + "</div>" +
        "</section>" +
        "</div></div>";
      try { document.body.classList.add("fo-boss-on"); } catch (eBc) {}
      var chB = page.querySelector("[data-boss-ch]");
